<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue';
import {ArrowDown,ArrowUp,ChevronsUpDown,GripVertical} from 'lucide-vue-next';
import {clampDatasetVisualWidth} from '../dataset-visual-layout';
const props=defineProps<{columnKey:string;name:string;alias?:string;description?:string;sortName:string;sortable?:boolean;direction?:'asc'|'desc';width:number;disabled?:boolean;dropSide?:'before'|'after'}>();
const emit=defineEmits<{sort:[];move:[from:string,to:string,after:boolean];resize:[width:number];'reset-width':[];resizing:[active:boolean];'move-step':[direction:-1|1];'drag-target':[key:string,after:boolean]}>();
const resizing=ref(false),dragging=ref(false);let startX=0,startWidth=0,pointerId=-1,resizeElement:HTMLElement|undefined,gripPointer=-1,gripX=0,gripY=0,gripElement:HTMLElement|undefined,gripTarget:{key:string;after:boolean}|undefined;
function gripStart(event:PointerEvent){if(props.disabled||event.button!==0)return;event.preventDefault();event.stopPropagation();gripPointer=event.pointerId;gripX=event.clientX;gripY=event.clientY;gripElement=event.currentTarget as HTMLElement;gripTarget=undefined;try{gripElement.setPointerCapture(gripPointer);}catch{window.addEventListener('pointermove',gripMove);window.addEventListener('pointerup',gripFinish);window.addEventListener('pointercancel',gripCancel);}}
function findTarget(event:PointerEvent){const header=document.elementFromPoint(event.clientX,event.clientY)?.closest<HTMLElement>('th[data-column-key]'),key=header?.dataset.columnKey;if(!header||!key||key===props.columnKey)return;const bounds=header.getBoundingClientRect();return {key,after:event.clientX>bounds.left+bounds.width/2};}
function gripMove(event:PointerEvent){if(event.pointerId!==gripPointer)return;event.preventDefault();if(!dragging.value&&Math.hypot(event.clientX-gripX,event.clientY-gripY)<6)return;dragging.value=true;gripTarget=findTarget(event);emit('drag-target',gripTarget?.key??'',gripTarget?.after??false);}
function stopGrip(){const element=gripElement,id=gripPointer;gripElement=undefined;gripPointer=-1;gripTarget=undefined;dragging.value=false;window.removeEventListener('pointermove',gripMove);window.removeEventListener('pointerup',gripFinish);window.removeEventListener('pointercancel',gripCancel);if(id!==-1)try{if(element?.hasPointerCapture(id))element.releasePointerCapture(id);}catch{/* Pointer was already released by the browser. */}emit('drag-target','',false);}
function gripEnd(event:PointerEvent,cancel=false){if(event.pointerId!==gripPointer)return;event.preventDefault();const target=dragging.value?findTarget(event)??gripTarget:undefined;if(!cancel&&target)emit('move',props.columnKey,target.key,target.after);stopGrip();}
const gripFinish=(event:PointerEvent)=>gripEnd(event),gripCancel=(event:PointerEvent)=>gripEnd(event,true);
onBeforeUnmount(()=>{if(gripPointer!==-1)stopGrip();if(resizing.value)stopResize();});
function startResize(event:PointerEvent){if(props.disabled||event.button!==0)return;event.preventDefault();event.stopPropagation();startX=event.clientX;startWidth=props.width;pointerId=event.pointerId;resizeElement=event.currentTarget as HTMLElement;resizing.value=true;emit('resizing',true);try{resizeElement.setPointerCapture(event.pointerId);}catch{window.addEventListener('pointermove',resize);window.addEventListener('pointerup',endResize);window.addEventListener('pointercancel',endResize);}}
function resize(event:PointerEvent){if(resizing.value&&event.pointerId===pointerId){event.preventDefault();emit('resize',clampDatasetVisualWidth(startWidth+event.clientX-startX));}}
function stopResize(){const id=pointerId,element=resizeElement;pointerId=-1;resizeElement=undefined;resizing.value=false;window.removeEventListener('pointermove',resize);window.removeEventListener('pointerup',endResize);window.removeEventListener('pointercancel',endResize);if(id!==-1)try{if(element?.hasPointerCapture(id))element.releasePointerCapture(id);}catch{/* Pointer was already released by the browser. */}emit('resizing',false);}
function endResize(event:PointerEvent){if(!resizing.value||event.pointerId!==pointerId)return;event.preventDefault();stopResize();}
function resizeKey(event:KeyboardEvent){if(props.disabled)return;if(event.key==='Escape'&&resizing.value){event.preventDefault();event.stopPropagation();emit('resize',startWidth);stopResize();return;}const delta=event.shiftKey?64:16;let width:number;if(event.key==='ArrowLeft')width=props.width-delta;else if(event.key==='ArrowRight')width=props.width+delta;else if(event.key==='Home')width=72;else if(event.key==='End')width=1200;else return;event.preventDefault();event.stopPropagation();emit('resize',clampDatasetVisualWidth(width));}
function moveKey(event:KeyboardEvent){if(event.key==='Escape'&&gripPointer!==-1){event.preventDefault();stopGrip();return;}if(props.disabled||!event.altKey||!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();event.stopPropagation();emit('move-step',event.key==='ArrowLeft'?-1:1);}
</script>
<template>
<div class="dw-visual-header" :class="{'dw-column-drop-before':dropSide==='before','dw-column-drop-after':dropSide==='after','dw-column-dragging':dragging,'dw-column-resizing':resizing}">
  <button type="button" class="dw-column-grip" :draggable="false" :disabled="disabled" :aria-label="'拖动排列 '+name" title="拖动改变列顺序；Alt＋左右方向键也可移动" @pointerdown="gripStart" @pointermove="gripMove" @pointerup="gripEnd($event)" @pointercancel="gripEnd($event,true)" @lostpointercapture="stopGrip" @click.stop @keydown="moveKey"><GripVertical :size="14"/></button>
  <button v-if="sortable!==false" type="button" class="dw-sort-header" :title="description" :aria-label="sortName+'；'+(direction==='asc'?'当前升序':direction==='desc'?'当前降序':'未排序')" @click="emit('sort')"><span class="dw-header-text"><span class="dw-header-id">{{name}}</span><small v-if="alias" class="dw-header-alias">{{alias}}</small></span><ArrowUp v-if="direction==='asc'" :size="13"/><ArrowDown v-else-if="direction==='desc'" :size="13"/><ChevronsUpDown v-else :size="12"/></button><span v-else class="dw-sort-header dw-static-header" :title="description"><span class="dw-header-text"><span class="dw-header-id">{{name}}</span><small v-if="alias" class="dw-header-alias">{{alias}}</small></span></span>
  <div class="dw-column-resizer" role="separator" aria-orientation="vertical" :aria-label="'调整 '+name+' 列宽'" :aria-valuenow="Math.round(width)" :aria-valuemin="72" :aria-valuemax="1200" :aria-disabled="disabled" :tabindex="disabled?-1:0" title="左右拖动调整列宽；方向键调节；双击恢复默认" @pointerdown="startResize" @pointermove="resize" @pointerup="endResize" @pointercancel="endResize" @lostpointercapture="resizing&&stopResize()" @keydown="resizeKey" @click.stop @dblclick.stop="emit('reset-width')"/>
</div>
</template>
